<fieldset class="sale-line panel"><legend>Barang / jasa</legend>
<div class="form-grid sale-item-grid"><label>Jenis item<select class="line-type" name="items[{{ $index }}][type]"><option value="product" @selected(($line['type']??'product')==='product')>Produk</option><option value="service" @selected(($line['type']??'')==='service')>Jasa servis</option></select></label>
<div class="product-field"><label>Produk<input type="search" class="product-search" autocomplete="off" placeholder="Cari nama atau SKU produk" aria-label="Cari produk"><small>Ketik nama atau kode produk, lalu pilih hasil pencarian.</small></label><div class="product-results" hidden aria-label="Hasil pencarian produk"></div><select hidden aria-hidden="true" tabindex="-1" class="line-product" name="items[{{ $index }}][product_id]"><option value="">Pilih produk</option>@foreach($products as $p)<option value="{{ $p->id }}" data-price="{{ $p->sale_price }}" data-sku="{{ $p->sku }}" @selected(($line['product_id']??'')==$p->id)>{{ $p->name }} — @rupiah($p->sale_price) — stok {{ $p->available_stock }}</option>@endforeach</select></div>
<label class="service-field">Pekerjaan / nama jasa<input name="items[{{ $index }}][name]" value="{{ $line['name']??'' }}" maxlength="150" placeholder="Contoh: Instalasi Windows"><small>Tulis pekerjaan yang dilakukan untuk pelanggan.</small></label>
<label class="service-field">Biaya (Rp)<input class="line-price" type="number" name="items[{{ $index }}][price]" value="{{ $line['price']??'' }}" min="0" max="1000000000" step="1" placeholder="Contoh: 100000"><small>Biaya yang dibayar pelanggan untuk satu jasa.</small></label>
<label>Jumlah (unit)<input class="line-quantity" type="number" name="items[{{ $index }}][quantity]" value="{{ $line['quantity']??1 }}" min="1" max="1000" required><small>Isi 1 untuk satu barang atau satu pekerjaan.</small></label></div>
<div class="summary-line"><span>Subtotal: <strong class="line-subtotal">Rp 0</strong></span><button type="button" class="secondary remove-line">Hapus baris</button></div>
</fieldset>
